import{_ as p,a0 as m,w as d,s as n,ao as i,I as s,x as e,a1 as o,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在Fedora或CentOS上使用Samba共享文件夹 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Fedora或CentOS上使用Samba共享文件夹 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Fedora或CentOS上使用Samba共享文件夹 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Fedora或CentOS上使用Samba共享文件夹 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150318 How to share a directory with Samba on Fedora or CentOS","title":"如何在Fedora或CentOS上使用Samba共享文件夹","tag":"201505","desc":""},"relativePath":"201505/20150318 How to share a directory with Samba on Fedora or CentOS.md","filePath":"[post].md"}'),b={name:"201505/20150318 How to share a directory with Samba on Fedora or CentOS.md"};function l(c,a,S,u,h,f){const t=m("Link");return d(),n("div",null,[a[13]||(a[13]=i(`<h1 id="如何在fedora或centos上使用samba共享文件夹" tabindex="-1">如何在Fedora或CentOS上使用Samba共享文件夹 <a class="header-anchor" href="#如何在fedora或centos上使用samba共享文件夹" aria-label="Permalink to “如何在Fedora或CentOS上使用Samba共享文件夹”">​</a></h1><p>如今，无论在家里或者是办公场所，不同的电脑之间共享文件夹已不是什么新鲜事了。在这种趋势下，现代操作系统通过网络文件系统的方式使得电脑间数据的交换变得简单而透明。如果您工作的环境中既有微软的Windows又有Linux，那么，一个共享文件及目录的方式便是通过一个跨平台网络文件共享协议：SMB/CIFS。Windows原生的支持SMB/CIFS，Linux也通过开源的软件Samba实现了SMB/CIFS协议。</p><p>在这篇文章中，我们将展示<strong>如何使用Samba共享文件夹</strong>。我们使用的Linux平台是<strong>Fedora或CentOS</strong>。这篇文章分为四部分。首先，我们在Fedora/CentOS环境下安装Sambe。接着，我们讨论如何调整SELinux和防火墙配置以允许Samba的文件共享。最后我们介绍如何使用Samba来共享文件夹。</p><h3 id="步骤1-在fedora和centos上安装samba" tabindex="-1">步骤1：在Fedora和CentOS上安装Samba <a class="header-anchor" href="#步骤1-在fedora和centos上安装samba" aria-label="Permalink to “步骤1：在Fedora和CentOS上安装Samba”">​</a></h3><p>首先，安装Samba以及进行一些基本的配置。</p><p>检验Samba是否已经安装在您的系统中：</p><pre><code>$ rpm -q samba samba-common samba-client 
</code></pre><p>如果上面的命令没有任何输出，这意味着Samba并未安装。这时，应使用下面的命令来安装Samba。</p><pre><code>$ sudo yum install samba samba-common samba-client 
</code></pre><p>接下来，创建一个用于在网络中共享的本地文件夹。这个文件夹应该以Samba共享的方式导出到远程的用户。在这个指南中，我们会在顶层文件夹&#39;/&#39;中创建这个文件夹，因此，请确保您有相应的权限。</p><pre><code>$ sudo mkdir /shared 
</code></pre><p>如果您想在您的home文件夹内创建共享文件夹（例如，~/shared），您必须激活SELinux中Samba的home文件夹共享选项，具体将在后面提到。</p><p>在创建/shared文件夹后，设置文件夹权限以保证其余用户可以访问它。</p><pre><code>$ sudo chmod o+rw /shared 
</code></pre><p>如果您不想其他用户对该文件夹拥有写权限，您需要移除命令中的&#39;w&#39;选项。</p><pre><code>$ sudo chmod o+r /shared 
</code></pre><p>接下来，创建一个空文件来测试。这个文件可以被用来验证Samba的共享已经被挂载。</p><pre><code>$ sudo touch /shared/file1 
</code></pre><h3 id="步骤2-为samba配置selinux" tabindex="-1">步骤2：为Samba配置SELinux <a class="header-anchor" href="#步骤2-为samba配置selinux" aria-label="Permalink to “步骤2：为Samba配置SELinux”">​</a></h3><p>接下来，我们需要再次配置SELinux。在Fedora和CentOS发行版中SELinux是默认开启的。SELinux仅在正确的安全配置下才允许Samba读取和修改文件或文件夹。（例如，加上&#39;samba_share_t&#39;属性标签）。</p><p>下面的命令为文件的配置添加必要的标签：</p><pre><code>$ sudo semanage fcontext -a -t samba_share_t &quot;&lt;directory&gt;(/.*)?&quot; 
</code></pre><p>将<code>&lt;directory&gt;</code>替换为我们之前为Samba共享创建的本地文件夹（例如，/shared）：</p><pre><code>$ sudo semanage fcontext -a -t samba_share_t &quot;/shared(/.*)?&quot; 
</code></pre><p>我们必须执行restorecon命令来激活修改的标签，命令如下：</p><pre><code>$ sudo restorecon -R -v /shared 
</code></pre><p><img src="https://farm9.staticflickr.com/8584/16652774078_2055f45f70_b.jpg" alt=""></p><p>为了通过Samba共享在我们home文件夹内的文件夹，我们必须在SELinux中开启共享home文件夹的选项，该选项默认被关闭。下面的命令能达到该效果。如果您并未共享您的home文件夹，那么您可以跳过该步骤。</p><pre><code>$ sudo setsebool -P samba_enable_home_dirs 1 
</code></pre><h3 id="步骤3-为samba配置防火墙" tabindex="-1">步骤3：为Samba配置防火墙 <a class="header-anchor" href="#步骤3-为samba配置防火墙" aria-label="Permalink to “步骤3：为Samba配置防火墙”">​</a></h3><p>下面的命令用来打开防火墙中Samba共享所需的TCP/UDP端口。</p><p>如果您在使用firewalld（例如，在Fedora和CentOS7下），接下来的命令将会永久的修改Samba相关的防火墙规则。</p><pre><code>$ sudo firewall-cmd --permanent --add-service=samba 
</code></pre><p>如果您在防火墙中使用iptables（例如，CentOS6或者更早的版本），可以使用下面的命令来打开Samba必要的向外的端口。</p><pre><code>$ sudo vi /etc/sysconfig/iptables 
</code></pre><hr><pre><code>-A RH-Firewall-1-INPUT -m state --state NEW -m tcp -p tcp --dport 445 -j ACCEPT
-A RH-Firewall-1-INPUT -m state --state NEW -m udp -p udp --dport 445 -j ACCEPT
-A RH-Firewall-1-INPUT -m state --state NEW -m udp -p udp --dport 137 -j ACCEPT
-A RH-Firewall-1-INPUT -m state --state NEW -m udp -p udp --dport 138 -j ACCEPT
-A RH-Firewall-1-INPUT -m state --state NEW -m tcp -p tcp --dport 139 -j ACCEPT
</code></pre><p>然后重启iptables服务：</p><pre><code>$ sudo service iptables restart 
</code></pre><h3 id="步骤4-更改samba配置" tabindex="-1">步骤4：更改Samba配置 <a class="header-anchor" href="#步骤4-更改samba配置" aria-label="Permalink to “步骤4：更改Samba配置”">​</a></h3><p>后面的步骤用来配置Samba以将本地文件夹导出为Samba共享文件夹。</p><p>使用文件编辑器打开Samba配置文件，并将下面的行添加到文件的末尾。</p><pre><code>$ sudo nano /etc/samba/smb.conf 
</code></pre><hr><pre><code>[myshare]
comment=my shared files
path=/shared
public=yes
writeable=yes
</code></pre><p>上面在括号内的文本（例如，&quot;myshare&quot;）是Samba共享的资源的名字，它被用来从远程主机存取Samba共享。</p><p>创建Samba用户帐户，这是挂载和导出Samba文件系统所必须的。我们可以使用smbpasswd工具来创建一个Samba用户。注意，Samba用户帐户必须是已有的Linux用户。如果您尝试使用smbpasswd添加一个不存在的用户，它会返回一个错误的消息。</p><p>如果您不想使用任何已存在的Linux用户作为Samba用户，您可以在您的系统中创建一个新的用户。为安全起见，设置新用户的登录脚本为/sbin/nologin，并且不创建该用户的home文件夹。</p><p>在这个例子中，我们创建了一个名叫&quot;sambaguest&quot;的用户，如下：</p><pre><code>$ sudo useradd -M -s /sbin/nologin sambaguest
$ sudo passwd sambaguest 
</code></pre><p><img src="https://farm9.staticflickr.com/8702/16814479366_53f540d3ba_b.jpg" alt=""></p><p>在创建一个新用户后，使用smbpasswd命令添加Samba用户。当这个命令询问一个密码时，您可以键入一个与其用户密码不同的密码。</p><pre><code>$ sudo smbpasswd -a sambaguest
</code></pre><p>激活Samba服务，并检测Samba服务是否在运行。</p><pre><code>$ sudo systemctl enable smb.service
$ sudo systemctl start smb.service
$ sudo systemctl is-active smb 
</code></pre><p><img src="https://farm8.staticflickr.com/7607/16652984770_622f24bccc_b.jpg" alt=""></p><p>使用下面的命令来查看Samba中共享的文件夹列表。</p><pre><code>$ smbclient -U sambaguest -L localhost 
</code></pre><p><img src="https://farm8.staticflickr.com/7281/16220411103_06bf585901_b.jpg" alt=""></p><p>接下来是在Thunar文件管理器中访问Samba共享文件夹以及对file1进行拷贝复制的截图。注意，Samba的共享内容可以通过在Thunar中通过 <code>smb://&lt;samba-server-IP-address&gt;/myshare</code> 这个地址来访问。</p><p><img src="https://farm8.staticflickr.com/7644/16218011174_c8b34fcedc_b.jpg" alt=""></p><hr>`,62)),s("p",null,[a[1]||(a[1]=e("via: ",-1)),o(t,{href:"http://xmodulo.com/share-directory-samba-fedora-centos.html"},{default:r(()=>[...a[0]||(a[0]=[e("http://xmodulo.com/share-directory-samba-fedora-centos.html",-1)])]),_:1})]),s("p",null,[a[5]||(a[5]=e("作者：",-1)),o(t,{href:"http://xmodulo.com/author/kristophorus"},{default:r(()=>[...a[2]||(a[2]=[e("Kristophorus Hadiono",-1)])]),_:1}),a[6]||(a[6]=e(" 译者：",-1)),o(t,{href:"https://github.com/wwy-hust"},{default:r(()=>[...a[3]||(a[3]=[e("wwy-hust",-1)])]),_:1}),a[7]||(a[7]=e(" 校对：",-1)),o(t,{href:"https://github.com/wxy"},{default:r(()=>[...a[4]||(a[4]=[e("wxy",-1)])]),_:1})]),s("p",null,[a[10]||(a[10]=e("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...a[8]||(a[8]=[e("LCTT",-1)])]),_:1}),a[11]||(a[11]=e(" 原创翻译，",-1)),o(t,{href:"http://linux.cn/"},{default:r(()=>[...a[9]||(a[9]=[e("Linux中国",-1)])]),_:1}),a[12]||(a[12]=e(" 荣誉推出",-1))])])}const g=p(b,[["render",l]]);export{T as __pageData,g as default};
